/** Narration clips: generated by narrate.cjs (or supplied through NARRATION_DIR) and described by a manifest. */
const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");
const { GAP, PROMO_DIR } = require("./config.cjs");

/** Creates the clips in `tmpDir` and returns { scene: [{ text, file, seconds }] }; empty when NARRATION=0. */
function generateNarration(tmpDir) {
  if (process.env.NARRATION === "0") return {};
  const out = path.join(tmpDir, "narr");
  execFileSync("node", [path.join(PROMO_DIR, "narrate.cjs"), out], { stdio: "inherit" });
  return JSON.parse(fs.readFileSync(path.join(out, "manifest.json"), "utf8"));
}

/** Seconds of speech in a scene, including the pauses between sentences. */
const spokenSeconds = (narration, scene) => (narration[scene] || []).reduce((sum, clip) => sum + clip.seconds + GAP, 0);

module.exports = { generateNarration, spokenSeconds };
